const deal = $('Lookup Deal').first().json;
const property = $('Lookup Property').first().json;
const config = $('Get Property Configuration').first().json;
const incomingData = $('Extract Incoming Data').first().json;

// Calculate nights if not already set
let nights = deal.nights;
if (!nights && deal.check_in && deal.check_out) {
  const checkIn = new Date(deal.check_in);
  const checkOut = new Date(deal.check_out);
  nights = Math.ceil((checkOut - checkIn) / (1000 * 60 * 60 * 24));
}

const systemPrompt = `You are a professional property manager for ${property.property_name}.

**BOOKING DETAILS:**
Guest: ${deal.client_name}
Dates: ${deal.check_in} to ${deal.check_out}
Nights: ${nights || 'calculating...'}
Rate: $${property.per_day_rate}/night
Base Rates: $${property.per_day_rate}/day, $${property.per_week_rate}/week, $${property.per_month_rate}/month

**PROPERTY INFORMATION:**
${property.description}

**AMENITIES:**
${property.amenities}

**WIFI CREDENTIALS:**
Network: "${property.wifi_network}"
Password: ${property.wifi_password}

**CHECK-IN/OUT:**
Check-in Time: ${property.check_in_time}
Check-out Time: ${property.check_out_time}

**HOUSE RULES:**
${property.house_rules}

**YOUR ROLE & RESPONSIBILITIES:**
1. Be warm, helpful, and professional at all times
2. Answer questions about:
   - Property features and amenities
   - Local area and attractions
   - Check-in/check-out procedures
   - House rules and policies
   - WiFi and utilities
3. Provide accurate information based on the property details above
4. Keep responses concise (under 150 words) and friendly

**CRITICAL ESCALATION RULES:**
You MUST detect and escalate the following situations by responding with these EXACT control phrases:

🔴 PRICING/NEGOTIATION - If guest mentions:
   - Price negotiation, discounts, or lower rates
   - "Can you do better on price?"
   - "Is there any flexibility?"
   - "That's too expensive"
   - Any request to change the quoted price
   → Response: "ESCALATE_TO_CONTACT_PRICING" (followed by a brief acknowledgment)

🔴 BOOKING CONFIRMATION - If guest says:
   - "I want to book"
   - "Let's proceed with the reservation"
   - "I'd like to confirm"
   - "How do I pay?"
   - Any clear intent to complete the booking
   → Response: "ESCALATE_TO_CONTACT_BOOKING" (followed by confirmation message)

🔴 PARTY/EVENT - If guest mentions:
   - Party, celebration, event, or gathering
   - "We're planning a birthday party"
   - "Having friends over"
   - Large group activities
   - More guests than originally stated
   → Response: "ESCALATE_TO_CONTACT_PARTY" (followed by a polite note)

**CONVERSATION HISTORY:**
${deal.conversation_history || 'This is the first message from the guest.'}

**LATEST GUEST MESSAGE:**
"${incomingData.latest_client_message}"

Respond naturally and professionally. Include the escalation control phrase ONLY if one of the escalation conditions is met.`;

return [{
  json: {
    model: 'gpt-4o-mini',
    temperature: 0.7,
    max_tokens: 500,
    messages: [
      {
        role: 'system',
        content: systemPrompt
      },
      {
        role: 'user',
        content: incomingData.latest_client_message
      }
    ],
    deal: deal,
    property: property,
    config: config,
    incoming: incomingData
  }
}];

const openaiResponse = $input.first().json;
const promptData = $('Build System Prompt').first().json;

const aiResponse = openaiResponse.choices[0].message.content;
const deal = promptData.deal;
const config = promptData.config;
const incoming = promptData.incoming;

// Initialize routing decision
let action = 'continue_conversation';
let designatedContact = null;
let contactMethod = null;
let escalationType = null;

// Detect escalation signals
if (aiResponse.includes('ESCALATE_TO_CONTACT_PRICING')) {
  action = 'send_to_pricing_contact';
  escalationType = 'pricing';
  designatedContact = config.pricing_decision_contact;
  contactMethod = config.pricing_decision_contact_method;
} else if (aiResponse.includes('ESCALATE_TO_CONTACT_BOOKING')) {
  action = 'send_to_booking_contact';
  escalationType = 'booking';
  designatedContact = config.booking_approval_contact;
  contactMethod = config.booking_approval_contact_method;
} else if (aiResponse.includes('ESCALATE_TO_CONTACT_PARTY')) {
  action = 'send_to_party_contact';
  escalationType = 'party';
  designatedContact = config.party_inquiry_contact;
  contactMethod = config.party_inquiry_contact_method;
}

// Clean the AI response by removing control phrases
const cleanedResponse = aiResponse
  .replace(/ESCALATE_TO_CONTACT_PRICING/g, '')
  .replace(/ESCALATE_TO_CONTACT_BOOKING/g, '')
  .replace(/ESCALATE_TO_CONTACT_PARTY/g, '')
  .trim();

return [{
  json: {
    action: action,
    escalation_type: escalationType,
    ai_response: cleanedResponse,
    deal_id: deal.deal_id,
    client_name: deal.client_name,
    property_name: deal.property_name,
    check_in: deal.check_in,
    check_out: deal.check_out,
    nights: deal.nights,
    guests: deal.guests,
    daily_rate: deal.daily_rate,
    total_value: deal.total_value,
    conversation_history: deal.conversation_history || '',
    latest_client_message: incoming.latest_client_message,
    client_phone: deal.client_phone,
    channel_type: deal.channel_type,
    designated_contact: designatedContact,
    contact_method: contactMethod,
    property_config: config
  }
}];

const data = $input.first().json;

// Build conversation history entry
const currentHistory = data.conversation_history || '';
const timestamp = new Date().toISOString();
const newEntry = `\n[${timestamp}]\nGuest: ${data.latest_client_message}\nManager: ${data.ai_response}`;

// Keep last 2000 characters to prevent overflow
const updatedHistory = (currentHistory + newEntry).slice(-2000);

return [{
  json: {
    deal_id: data.deal_id,
    conversation_history: updatedHistory,
    last_message_timestamp: timestamp,
    ...data
  }
}];

const data = $input.first().json;
const config = data.property_config;

// Format pricing decision message
const message = `💰 *PRICING NEGOTIATION REQUIRED*\n\n` +
  `👤 Guest: ${data.client_name}\n` +
  `🏠 Property: ${data.property_name}\n` +
  `📅 Dates: ${data.check_in} → ${data.check_out}\n` +
  `🌙 Nights: ${data.nights}\n` +
  `👥 Guests: ${data.guests}\n\n` +
  `💵 Current rate: $${data.daily_rate}/night\n` +
  `💰 Total quoted: $${data.total_value}\n\n` +
  `📝 *Guest's request:*\n` +
  `"${data.latest_client_message}"\n\n` +
  `💬 *Recent conversation:*\n` +
  `${data.conversation_history?.slice(-500) || 'First message'}\n\n` +
  `⚡ *What would you like to do?*`;

// Telegram inline keyboard
const keyboard = {
  inline_keyboard: [
    [{text: '✅ Accept Their Offer', callback_data: `accept_${data.deal_id}`}],
    [{text: '💬 Make Counter Offer', callback_data: `counter_${data.deal_id}`}],
    [{text: '❌ Decline Politely', callback_data: `decline_${data.deal_id}`}]
  ]
};

return [{
  json: {
    message: message,
    keyboard: keyboard,
    contact_phone: data.designated_contact,
    contact_method: data.contact_method,
    deal_id: data.deal_id,
    client_phone: data.client_phone,
    channel_type: data.channel_type,
    ...data
  }
}];

const response = $input.first().json;

// Parse the decision from contact
let decision = '';
let dealId = '';

if (response.callback_query) {
  // Telegram callback
  decision = response.callback_query.data.split('_')[0];
  dealId = response.callback_query.data.split('_')[1];
} else if (response.Body) {
  // SMS response
  const body = response.Body.toUpperCase();
  if (body.includes('ACCEPT')) decision = 'accept';
  else if (body.includes('COUNTER')) decision = 'counter';
  else if (body.includes('DECLINE')) decision = 'decline';

  // Extract deal ID from message
  const match = body.match(/DEAL:\s*([A-Z0-9-]+)/i);
  dealId = match ? match[1] : response.deal_id;
}

// Generate guest response based on decision
let messageToGuest = '';
let updateStatus = '';

if (decision === 'accept') {
  messageToGuest = `Great news! 🎉\n\nYour pricing request has been approved. We're happy to work with you on this.\n\nWe'll send payment instructions shortly to complete your booking!`;
  updateStatus = 'pricing_approved';
} else if (decision === 'counter') {
  messageToGuest = `Thank you for your interest! We'd like to make you a counter offer.\n\nOur property manager will reach out shortly with a proposal that works for both of us.`;
  updateStatus = 'pricing_counter_pending';
} else if (decision === 'decline') {
  messageToGuest = `Thank you for your interest in our property.\n\nUnfortunately, we're unable to adjust the pricing for these dates. However, we'd be happy to help you find alternative dates or discuss other properties that might fit your budget.\n\nPlease let us know if you'd like to explore other options!`;
  updateStatus = 'pricing_declined';
}

return [{
  json: {
    decision: decision,
    deal_id: dealId,
    message_to_guest: messageToGuest,
    update_status: updateStatus,
    channel_type: response.channel_type || 'sms',
    client_phone: response.client_phone
  }
}];

const data = $input.first().json;

const message = `🎉 *GUEST WANTS TO BOOK!*\n\n` +
  `👤 Guest: ${data.client_name}\n` +
  `🏠 Property: ${data.property_name}\n` +
  `📅 Dates: ${data.check_in} → ${data.check_out}\n` +
  `🌙 Nights: ${data.nights}\n` +
  `👥 Guests: ${data.guests}\n` +
  `💰 Total: $${data.total_value}\n\n` +
  `💬 *Guest said:*\n` +
  `"${data.latest_client_message}"\n\n` +
  `✅ *Ready to send payment instructions?*`;

const keyboard = {
  inline_keyboard: [
    [{text: '💳 Send Payment Instructions', callback_data: `payment_${data.deal_id}`}],
    [{text: '❓ Request More Info First', callback_data: `moreinfo_${data.deal_id}`}]
  ]
};

return [{
  json: {
    message: message,
    keyboard: keyboard,
    contact_phone: data.designated_contact,
    contact_method: data.contact_method,
    ...data
  }
}];

const response = $input.first().json;

let action = '';
let dealId = '';

if (response.callback_query) {
  action = response.callback_query.data.split('_')[0];
  dealId = response.callback_query.data.split('_')[1];
} else if (response.Body) {
  const body = response.Body.toUpperCase();
  if (body.includes('PAYMENT')) action = 'payment';
  else if (body.includes('MOREINFO')) action = 'moreinfo';

  const match = body.match(/DEAL:\s*([A-Z0-9-]+)/i);
  dealId = match ? match[1] : response.deal_id;
}

let messageToGuest = '';

if (action === 'payment') {
  messageToGuest = `Fantastic! 🎉 Your booking is confirmed!\n\n` +
    `💳 *PAYMENT INSTRUCTIONS:*\n\n` +
    `Please send payment via:\n` +
    `• Zelle: payments@property.com\n` +
    `• Venmo: @PropertyManager\n` +
    `• Bank Transfer: [Account details]\n\n` +
    `Amount due: $${response.total_value}\n\n` +
    `Once we receive your payment, we'll send you:\n` +
    `✅ Official booking confirmation\n` +
    `✅ Check-in instructions\n` +
    `✅ Property access codes\n\n` +
    `Reply with payment confirmation when sent!`;
} else if (action === 'moreinfo') {
  messageToGuest = `Thank you for your interest! 😊\n\n` +
    `We'd love to learn more about your stay to ensure everything is perfect.\n\n` +
    `Could you share:\n` +
    `• Purpose of your visit?\n` +
    `• Any special requests?\n` +
    `• Estimated arrival time?\n\n` +
    `Our property manager will be in touch shortly!`;
}

return [{
  json: {
    action: action,
    deal_id: dealId,
    message_to_guest: messageToGuest,
    channel_type: response.channel_type || 'sms',
    client_phone: response.client_phone
  }
}];

const data = $input.first().json;
const config = data.property_config;
const partyPolicy = config.party_policy || 'case_by_case';

let message = `🎉 *PARTY/EVENT INQUIRY ALERT*\n\n`;
message += `⚠️ Guest has mentioned a party or event\n\n`;
message += `👤 Guest: ${data.client_name}\n`;
message += `🏠 Property: ${data.property_name}\n`;
message += `📅 Dates: ${data.check_in} → ${data.check_out}\n`;
message += `🌙 Nights: ${data.nights}\n`;
message += `👥 Declared guests: ${data.guests}\n\n`;
message += `💬 *Guest mentioned:*\n`;
message += `"${data.latest_client_message}"\n\n`;
message += `📋 *Recent conversation:*\n`;
message += `${data.conversation_history?.slice(-400) || 'First message'}\n\n`;

if (partyPolicy === 'recommend_decline') {
  message += `🚫 *YOUR POLICY: RECOMMEND DECLINE*\n\n`;
  message += `Your configuration suggests declining party inquiries, but the final decision is yours.\n\n`;
} else {
  message += `📝 *YOUR POLICY: Case-by-Case Review*\n\n`;
  message += `Please review this inquiry and decide how to proceed.\n\n`;
}

message += `*What would you like to do?*`;

const keyboard = {
  inline_keyboard: [
    [{text: '✅ Approve (Accept Risk)', callback_data: `approve_party_${data.deal_id}`}],
    [{text: '❌ Decline This Inquiry', callback_data: `decline_party_${data.deal_id}`}],
    [{text: '❓ Ask Guest More Questions', callback_data: `info_party_${data.deal_id}`}]
  ]
};

return [{
  json: {
    message: message,
    keyboard: keyboard,
    contact_phone: data.designated_contact,
    contact_method: data.contact_method,
    party_policy: partyPolicy,
    ...data
  }
}];

const response = $input.first().json;

let decision = '';
let dealId = '';

if (response.callback_query) {
  const data = response.callback_query.data;
  if (data.includes('approve_party_')) {
    decision = 'approve';
    dealId = data.replace('approve_party_', '');
  } else if (data.includes('decline_party_')) {
    decision = 'decline';
    dealId = data.replace('decline_party_', '');
  } else if (data.includes('info_party_')) {
    decision = 'info';
    dealId = data.replace('info_party_', '');
  }
} else if (response.Body) {
  const body = response.Body.toUpperCase();
  if (body.includes('APPROVE')) decision = 'approve';
  else if (body.includes('DECLINE')) decision = 'decline';
  else if (body.includes('INFO')) decision = 'info';

  const match = body.match(/DEAL:\s*([A-Z0-9-]+)/i);
  dealId = match ? match[1] : response.deal_id;
}

let messageToGuest = '';
let updateStatus = '';

if (decision === 'approve') {
  messageToGuest = `Great news! 🎉\n\n` +
    `We've reviewed your inquiry and we'd be happy to host you!\n\n` +
    `A few important reminders:\n` +
    `• Please respect our property and neighbors\n` +
    `• Noise ordinance is strictly enforced\n` +
    `• Maximum occupancy must be observed\n\n` +
    `We look forward to hosting you! Let us know if you'd like to proceed with booking.`;
  updateStatus = 'party_approved';
} else if (decision === 'decline') {
  messageToGuest = `Thank you for your interest in our property.\n\n` +
    `After careful consideration, we don't believe this property would be the best fit for your event.\n\n` +
    `We'd be happy to help you find an alternative property that better suits your needs. Please let us know if you'd like recommendations!`;
  updateStatus = 'party_declined';
} else if (decision === 'info') {
  messageToGuest = `Thanks for your interest! 😊\n\n` +
    `To ensure we can accommodate your event properly, could you please provide some additional details?\n\n` +
    `• What type of event/celebration?\n` +
    `• Approximately how many people?\n` +
    `• What time will activities start/end?\n` +
    `• Any special requirements?\n\n` +
    `This helps us ensure everything goes smoothly for your stay!`;
  updateStatus = 'party_info_requested';
}

return [{
  json: {
    decision: decision,
    deal_id: dealId,
    message_to_guest: messageToGuest,
    update_status: updateStatus,
    channel_type: response.channel_type || 'sms',
    client_phone: response.client_phone
  }
}];
